func TestSpecialItemRefusesUnsafeIntegerInLevel(t *testing.T) {
	pth := mustFirstExpectedPath(t, "SpecialItem")

	for _, value := range []int64{
		9007199254740992,
		-9007199254740992,
	} {
		jsonable := ourtesting.MustReadJsonable(pth)

		instance, deseriaErr := ourjsonization.SpecialItemFromJsonable(
			jsonable,
		)
		if !assertNoDeserializationError(t, deseriaErr, pth) {
			return
		}

		instance.SetLevel(value)

		assertSafeIntegerRefused(
			t,
			instance,
			"Level",
			"Level()",
			fmt.Sprintf(
				"Expected an integer, but got %d, "+
				"which is outside the safe integer range [-2^53 + 1, 2^53 - 1]",
				value,
			),
		)
	}
}

func TestSpecialItemAcceptsSafeIntegerInLevel(t *testing.T) {
	pth := mustFirstExpectedPath(t, "SpecialItem")

	for _, value := range []int64{
		9007199254740991,
		-9007199254740991,
	} {
		jsonable := ourtesting.MustReadJsonable(pth)

		instance, deseriaErr := ourjsonization.SpecialItemFromJsonable(
			jsonable,
		)
		if !assertNoDeserializationError(t, deseriaErr, pth) {
			return
		}

		instance.SetLevel(value)

		assertSafeIntegerAccepted(t, instance)
	}
}

